_bx = bx
def bx(x, y0, z, w, h, d, c, **k):
    """most boxes here were written with (x, z) as the low corner, a few as the centre: a box that spans the origin as written is a corner box"""
    if x < 0 < x + w: x += w/2
    if z < 0 < z + d: z += d/2
    return _bx(x, y0, z, w, h, d, c, **k)
