# ---------------------------------------------------------------- court and track tiles (4 m decals)
def court(n, base, line, mode):
    g = [bx(0, 0.0, 0, 4.0, 0.02, 4.0, base)]
    if mode == 'line': g += [bx(-2.0, 0.02, -0.04, 4.0, 0.005, 0.08, line)]
    if mode == 'corner': g += [bx(-2.0, 0.02, -0.04, 2.04, 0.005, 0.08, line), bx(-0.04, 0.02, -2.0, 0.08, 0.005, 2.04, line)]
    if mode == 'circle': g += [loft([[0, 0.02, 0, 1.8, 1.8], [0, 0.025, 0, 1.8, 1.8]], line, n=16), loft([[0, 0.025, 0, 1.72, 1.72], [0, 0.03, 0, 1.72, 1.72]], base, n=16)]
    if mode == 'key': g += [bx(-1.5, 0.02, -2.0, 0.08, 0.005, 3.0, line), bx(1.42, 0.02, -2.0, 0.08, 0.005, 3.0, line), bx(-1.5, 0.02, 1.0, 3.0, 0.005, 0.08, line), bx(-1.46, 0.02, -2.0, 2.92, 0.003, 3.0, 'courtR')]
    R(n, g, '%s court tile: %s' % ({'courtG': 'green', 'courtB': 'blue', 'courtR': 'red clay'}[base], {'plain': 'plain', 'line': 'one white line across the middle', 'corner': 'a white corner', 'circle': 'a white centre circle', 'key': 'a painted key (basketball)'}[mode]), use='floor tile')
for base, nm in (('courtG', 'green'), ('courtB', 'blue'), ('courtR', 'clay')):
    for mode in ('plain', 'line', 'corner'): court('court_%s_%s' % (nm, mode), base, 'line', mode)
court('court_blue_circle', 'courtB', 'line', 'circle'); court('court_blue_key', 'courtB', 'line', 'key')
